// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a1, uint256 a2) internal {
        a1 = bound(a1, 0, 1000000000000000000000000000000);
        a2 = bound(a2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a1 + a2);
        uint balBefore = address(c).balance;
        try c.deposit{value: a1}() {} catch { return; }
        try c.deposit{value: a2}() {} catch { return; }
        assertTrue(address(c).balance == balBefore + a1 + a2);
    }

    function testFuzz_run(uint256 a1, uint256 a2) public {
        _run(a1, a2);
    }

    receive() external payable {}
}
